local NetMaker = {}
local PRODUCTS = {
    iron_net = { name = "Železna mreža", ironCost = 1, woodCost = 2, leatherCost = 3, time = 5, cost = 155, prestige = 3, happiness = 2, description = "Železna mreža za ribolov in lov." },
    bronze_net = { name = "Bronasta mreža", bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 3, time = 7, cost = 380, prestige = 5, happiness = 3, description = "Bronasta mreža za trdovratne ulove." },
    silver_net = { name = "Srebrna mreža", silverCost = 1, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 3, time = 11, cost = 920, prestige = 10, happiness = 4, description = "Srebrna mreža za plemiške ribiče." },
    gilded_net = { name = "Pozlačena mreža", goldCost = 1, silverCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 3, time = 15, cost = 1980, prestige = 19, happiness = 5, description = "Pozlačena mreža za dvorne ribiče." },
    jewel_set_net = { name = "Draguljasta mreža", goldCost = 2, silverCost = 1, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 3, time = 19, cost = 4280, prestige = 35, happiness = 7, description = "Draguljasta mreža za kraljeve ribiče." },
    royal_sovereign_net = { name = "Kraljevski suverena mreža", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 4, time = 26, cost = 9200, prestige = 67, happiness = 13, description = "Suverena mreža z biseri za krono." },
}
local BUILDINGS = {
    net_workshop = { name = "Mrežna delavnica", cost = { gold = 315, wood = 180, stone = 130, iron = 6 }, upkeep = 6, qualityBonus = 5 },
    net_house = { name = "Mrežna hiša", cost = { gold = 1165, wood = 360, stone = 265, silver = 7, iron = 7 }, upkeep = 24, qualityBonus = 18 },
    master_net_atelier = { name = "Mojstrski mrežni atelje", cost = { gold = 2935, wood = 420, stone = 510, silver = 34, gold = 7 }, upkeep = 69, qualityBonus = 30 },
    sovereign_net_palace = { name = "Suverena mrežna palača", cost = { gold = 12780, wood = 645, stone = 820, gold = 82, jewel = 19 }, upkeep = 251, qualityBonus = 55, prestigeBonus = 50 },
}
NetMaker.ironStock = 10; NetMaker.bronzeStock = 8; NetMaker.woodStock = 14; NetMaker.leatherStock = 16; NetMaker.silverStock = 8; NetMaker.goldStock = 6; NetMaker.jewelStock = 4; NetMaker.pearlStock = 4
NetMaker.productStock = {}; NetMaker.buildings = {}; NetMaker.maker = nil; NetMaker.activeMaking = {}; NetMaker.totalProducts = 0; NetMaker.dayTimer = 0
function NetMaker.init() NetMaker.ironStock=10; NetMaker.bronzeStock=8; NetMaker.woodStock=14; NetMaker.leatherStock=16; NetMaker.silverStock=8; NetMaker.goldStock=6; NetMaker.jewelStock=4; NetMaker.pearlStock=4; NetMaker.productStock={}; NetMaker.buildings={}; NetMaker.maker=nil; NetMaker.activeMaking={}; NetMaker.totalProducts=0; NetMaker.dayTimer=0; print("[NetMaker] Royal Net Maker System initialized (6 products, 4 buildings)") end
function NetMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; NetMaker.maker={name=n or ("Mrežar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mrežar najet: %s (spretnost: %d)",NetMaker.maker.name,s),"success") end; return true end
function NetMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function NetMaker.build(id) local ok,e=NetMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(NetMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function NetMaker.getQualityBonus() local b=0; for _,bd in ipairs(NetMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function NetMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and NetMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and NetMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and NetMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and NetMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and NetMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and NetMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and NetMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and NetMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #NetMaker.buildings==0 then return false,"Potrebna mrežna delavnica" end; if not NetMaker.maker then return false,"Potreben mrežar" end; return true end
function NetMaker.make(pt,qty) qty=qty or 1; local ok,e=NetMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then NetMaker.ironStock=NetMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then NetMaker.bronzeStock=NetMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then NetMaker.woodStock=NetMaker.woodStock-d.woodCost*qty end; if d.leatherCost then NetMaker.leatherStock=NetMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then NetMaker.silverStock=NetMaker.silverStock-d.silverCost*qty end; if d.goldCost then NetMaker.goldStock=NetMaker.goldStock-d.goldCost*qty end; if d.jewelCost then NetMaker.jewelStock=NetMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then NetMaker.pearlStock=NetMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if NetMaker.maker then t=math.max(1,t-math.floor(NetMaker.maker.skill/13)) end; table.insert(NetMaker.activeMaking,{id="net_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function NetMaker.completeMaking(m) local q=1.0+(NetMaker.getQualityBonus()/100); if NetMaker.maker then q=q+(NetMaker.maker.skill/140) end; q=math.min(2.5,q); NetMaker.productStock[m.productType]=(NetMaker.productStock[m.productType] or 0)+m.quantity; NetMaker.totalProducts=NetMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if NetMaker.maker then NetMaker.maker.itemsMade=NetMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then NetMaker.maker.skill=math.min(100,NetMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mreža izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"net.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function NetMaker.update(dt) if not _G.state then return end; NetMaker.dayTimer=NetMaker.dayTimer+dt; if NetMaker.dayTimer>=30 then NetMaker.dayTimer=0; for i=#NetMaker.activeMaking,1,-1 do local m=NetMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then NetMaker.completeMaking(m); table.remove(NetMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(NetMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if NetMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function NetMaker.getStats() return {ironStock=NetMaker.ironStock,bronzeStock=NetMaker.bronzeStock,woodStock=NetMaker.woodStock,leatherStock=NetMaker.leatherStock,silverStock=NetMaker.silverStock,goldStock=NetMaker.goldStock,jewelStock=NetMaker.jewelStock,pearlStock=NetMaker.pearlStock,productStock=NetMaker.productStock,numBuildings=#NetMaker.buildings,hasMaker=NetMaker.maker~=nil,makerName=NetMaker.maker and NetMaker.maker.name or "—",makerSkill=NetMaker.maker and NetMaker.maker.skill or 0,activeMaking=#NetMaker.activeMaking,totalProducts=NetMaker.totalProducts} end
return NetMaker
